-- Exact Tawasi Products Synced from User Photos
INSERT INTO products (id, category, name, name_ar, description, description_ar, "basePrice", image, available, "isBestSeller", "isFeatured", "isPreOrder24h", "optionGroups", modifiers, ingredients, "order") VALUES
('uzbekian', 'main-dishes', 'Uzbekian', 'أوزباكيان', 'Luxurious Uzbek-style basmati pilaf rice layered with sliced carrots, onions, golden raisins, and authentic Uzbek spices. Available with fresh chicken or tender meat.', 'طبق أوزبكي فاخر بأرز البسمتي مع قطع الدجاج أو اللحم، شرحات بصل، شرحات الجزر، زبيب، وبهارات أوزبكية خاصة خالية من الغلوتين.', 4.75, 'assets/images/tawasi_uzbekian.jpg', true, false, false, true, '[{"id":"portion-choice","name":"Protein & Portion (Required)","type":"radio","name_ar":"الخيار والكمية (مطلوب)","options":[{"id":"chk-1","name":"1 Chicken","price":0,"default":true,"name_ar":"دجاجة"},{"id":"chk-2","name":"2 Chickens","price":7,"default":false,"name_ar":"دجاجتين"},{"id":"meat-1kg","name":"1 KG Meat","price":7,"default":false,"name_ar":"1 ك لحم"},{"id":"meat-2kg","name":"2 KG Meat","price":20,"default":false,"name_ar":"2 ك لحم"}],"required":true}]'::jsonb, '[{"id":"extra-daqoos","name":"Extra Daqoos Sauce","type":"add","price":0.5,"name_ar":"دقوس إضافي"},{"id":"extra-almonds","name":"Roasted Almonds & Nuts","type":"add","price":0.5,"name_ar":"لوز ومكسرات محمصة"}]'::jsonb, '[{"id":"rice","desc":"Authentic pilaf rice","icon":"assets/images/ing_bun.png","name":"Uzbek Basmati Rice","name_ar":"أرز بسمتي فاخر","removable":false},{"id":"protein","desc":"Choice of fresh chicken or tender meat","icon":"assets/images/ing_chicken.png","name":"Chicken or Meat Choice","name_ar":"خيار الدجاج أو اللحم","removable":false},{"id":"carrots","desc":"Sweet sliced carrots","icon":"assets/images/ing_tomato.png","name":"Sweet Carrot Slices","name_ar":"شرحات الجزر","removable":false},{"id":"raisins-onions","desc":"Golden raisins and caramelized onions","icon":"assets/images/ing_lettuce.png","name":"Raisins & Sliced Onions","name_ar":"زبيب وشرحات بصل","removable":false},{"id":"spices","desc":"Authentic Central Asian spices","icon":"assets/images/ing_sauce.png","name":"Gluten-Free Uzbek Spices","name_ar":"بهارات أوزبكية خاصة خالية من الغلوتين","removable":false}]'::jsonb, 58),
('biryani', 'main-dishes', 'Biryani', 'برياني', 'Layers of fragrant saffron basmati rice with aromatic spices, caramelized onions, and roasted nuts. Available with fresh chicken or tender meat.', 'أرز بسمتي فاخر بنكهة الزعفران والبهارات الغنية مع البصل المكرمل والمكسرات المحمصة. متوفر بخيار الدجاج أو اللحم.', 5, 'assets/images/tawasi_biryani.jpg', true, true, true, true, '[{"id":"portion-choice","name":"Protein & Portion (Required)","type":"radio","name_ar":"الخيار والكمية (مطلوب)","options":[{"id":"chk-1","name":"1 Chicken","price":0,"default":true,"name_ar":"دجاجة"},{"id":"chk-2","name":"2 Chickens","price":7,"default":false,"name_ar":"دجاجتين"},{"id":"meat-1kg","name":"1 KG Meat","price":7,"default":false,"name_ar":"1 ك لحم"},{"id":"meat-2kg","name":"2 KG Meat","price":20,"default":false,"name_ar":"2 ك لحم"}],"required":true}]'::jsonb, '[{"id":"extra-daqoos","name":"Extra Daqoos Sauce","type":"add","price":0.5,"name_ar":"دقوس إضافي"},{"id":"extra-almonds","name":"Roasted Almonds & Nuts","type":"add","price":0.5,"name_ar":"لوز ومكسرات محمصة"}]'::jsonb, '[{"id":"rice","desc":"Long grain saffron basmati rice","icon":"assets/images/ing_bun.png","name":"Saffron Basmati Rice","name_ar":"أرز بسمتي بالزعفران","removable":false},{"id":"protein","desc":"Choice of fresh chicken or tender meat","icon":"assets/images/ing_chicken.png","name":"Chicken or Meat Choice","name_ar":"خيار الدجاج أو اللحم","removable":false},{"id":"aromatics","desc":"Golden caramelized onions and crunchy nuts","icon":"assets/images/ing_lettuce.png","name":"Onions & Roasted Nuts","name_ar":"بصل ومكسرات محمصة","removable":false},{"id":"spices","desc":"Rich warming aromatic biryani spices","icon":"assets/images/ing_sauce.png","name":"Gluten-Free Biryani Spices","name_ar":"بهارات برياني خالية من الغلوتين","removable":false}]'::jsonb, 51),
('qidreh-khaliliyeh', 'main-dishes', 'Qidreh Khaliliyeh', 'قدرة خليلية', 'Heritage Hebron rice dish cooked in authentic baladi ghee with whole chickpeas, garlic cloves, onions, and heritage spices. Available with fresh chicken or tender meat.', 'أرز مطبوخ بالسمن البلدي مع قطع الدجاج أو اللحم، بصل، حمص حب، ثوم، وبهارات تراثية خالية من الغلوتين.', 4.5, 'assets/images/tawasi_qidreh.jpg', true, false, false, true, '[{"id":"portion-choice","name":"Protein & Portion (Required)","type":"radio","name_ar":"الخيار والكمية (مطلوب)","options":[{"id":"chk-1","name":"1 Chicken","price":0,"default":true,"name_ar":"دجاجة"},{"id":"chk-2","name":"2 Chickens","price":7,"default":false,"name_ar":"دجاجتين"},{"id":"meat-1kg","name":"1 KG Meat","price":7,"default":false,"name_ar":"1 ك لحم"},{"id":"meat-2kg","name":"2 KG Meat","price":20,"default":false,"name_ar":"2 ك لحم"}],"required":true}]'::jsonb, '[{"id":"extra-daqoos","name":"Extra Daqoos Sauce","type":"add","price":0.5,"name_ar":"دقوس إضافي"},{"id":"extra-almonds","name":"Roasted Almonds & Nuts","type":"add","price":0.5,"name_ar":"لوز ومكسرات محمصة"}]'::jsonb, '[{"id":"rice","desc":"Cooked with authentic baladi ghee","icon":"assets/images/ing_bun.png","name":"Ghee-Cooked Rice","name_ar":"أرز مطبوخ بالسمن البلدي","removable":false},{"id":"protein","desc":"Choice of fresh chicken or tender meat","icon":"assets/images/ing_chicken.png","name":"Chicken or Meat Choice","name_ar":"خيار الدجاج أو اللحم","removable":false},{"id":"chickpeas","desc":"Plump garbanzo beans","icon":"assets/images/ing_bun.png","name":"Whole Chickpeas","name_ar":"حمص حب","removable":false},{"id":"garlic-onion","desc":"Whole garlic cloves and sweet onions","icon":"assets/images/ing_lettuce.png","name":"Garlic Cloves & Onions","name_ar":"ثوم وبصل","removable":false},{"id":"spices","desc":"Authentic Hebron spice mix","icon":"assets/images/ing_sauce.png","name":"Gluten-Free Qidreh Spices","name_ar":"بهارات تراثية خالية من الغلوتين","removable":false}]'::jsonb, 56),
('armenian-kofta', 'main-dishes', 'Armenian Kofta with Potatoes', 'كفتة أرمنية بالبطاطا', 'Grilled kofta with tomato slices and gluten-free seasonings, served with rice or mashed potatoes. Available with fresh chicken or meat.', 'كفتة مشوية، شرحات الطماطم، بهارات خالية من الغلوتين، تقدم مع الرز أو بطاطا مهروسة. متوفرة بالدجاج أو اللحم.', 5.75, 'assets/images/tawasi_armenian_kofta.webp', true, false, false, true, '[{"id":"portion-choice","name":"Protein & Portion (Required)","type":"radio","name_ar":"الخيار والكمية (مطلوب)","options":[{"id":"chk-1","name":"1 Chicken","price":0,"default":true,"name_ar":"دجاجة"},{"id":"chk-2","name":"2 Chickens","price":7,"default":false,"name_ar":"دجاجتين"},{"id":"meat-1kg","name":"1 KG Meat","price":7,"default":false,"name_ar":"1 ك لحم"},{"id":"meat-2kg","name":"2 KG Meat","price":20,"default":false,"name_ar":"2 ك لح��"}],"required":true}]'::jsonb, '[{"id":"extra-daqoos","name":"Extra Daqoos Sauce","type":"add","price":0.5,"name_ar":"دقوس إضافي"},{"id":"extra-almonds","name":"Roasted Almonds & Nuts","type":"add","price":0.5,"name_ar":"لوز ومكسرات محمصة"}]'::jsonb, '[{"id":"kofta","desc":"Seasoned grilled kofta","icon":"assets/images/ing_chicken.png","name":"Grilled Kofta","name_ar":"كفتة مشوية","removable":false},{"id":"tomatoes","desc":"Fresh tomato slices","icon":"assets/images/ing_tomato.png","name":"Tomato Slices","name_ar":"شرحات الطماطم","removable":false},{"id":"spices","desc":"Traditional seasonings","icon":"assets/images/ing_sauce.png","name":"Gluten-Free Seasoning","name_ar":"بهارات خالية من الغلوتين","removable":false},{"id":"side","desc":"Served with rice or mashed potatoes","icon":"assets/images/ing_bun.png","name":"Rice or Mashed Potatoes","name_ar":"تقدم مع الرز أو بطاطا مهروسة","removable":false}]'::jsonb, 60),
('sayadieh-fish', 'main-dishes', 'Fish Sayadieh', 'صيادية سمك', 'Crispy fried fish fillet, caramelized onions, tomatoes, dried lime, cooked with rice in rich gluten-free seafood spices. Available in 1 KG or 2 KG fish portion.', 'فيلية سمك مقلي، بصل مكرمل، طماطم، لومي، مطبوخ مع الرز بالبهارات البحرية الغنية والخالية من الجلوتين. متوفر بخيار 1 ك أو 2 ك سمك.', 5.75, 'assets/images/tawasi_sayadieh.webp', true, false, false, true, '[{"id":"fish-portion","name":"Fish Quantity (Required)","type":"radio","name_ar":"كمية السمك (مطلوب)","options":[{"id":"fish-1kg","name":"1 KG Fish","price":0,"default":true,"name_ar":"1 ك سمك"},{"id":"fish-2kg","name":"2 KG Fish","price":8,"default":false,"name_ar":"2 ك سمك"}],"required":true}]'::jsonb, '[{"id":"extra-daqoos","name":"Extra Daqoos Sauce","type":"add","price":0.5,"name_ar":"دقوس إضافي"},{"id":"extra-almonds","name":"Roasted Almonds & Nuts","type":"add","price":0.5,"name_ar":"لوز ومكسرات محمصة"}]'::jsonb, '[{"id":"fish","desc":"Golden crispy fried fish fillets","icon":"assets/images/ing_chicken.png","name":"Fried Fish Fillet","name_ar":"فيلية سمك مقلي","removable":false},{"id":"rice","desc":"Rice cooked with caramelized onions and seafood spices","icon":"assets/images/ing_bun.png","name":"Caramelized Onion Rice","name_ar":"أرز مطبوخ بالبصل المكرمل","removable":false},{"id":"aromatics","desc":"Stewed tomatoes and black lime","icon":"assets/images/ing_tomato.png","name":"Tomatoes & Dried Lime","name_ar":"طماطم ولومي","removable":false},{"id":"spices","desc":"Special rich seafood spices","icon":"assets/images/ing_sauce.png","name":"Gluten-Free Seafood Spices","name_ar":"بهارات بحرية غنية خالية من الجلوتين","removable":false}]'::jsonb, 63),
('zurbian', 'main-dishes', 'Zurbian', 'زربيان', 'Traditional Adeni spiced basmati rice layered with potatoes, onions, tomatoes, dried lime, and special spices. Available with fresh chicken or tender meat.', 'أرز بسمتي مع خيار الدجاج المشوي أو اللحم، بصل، طماطم، بطاطا، لومي، وبهارات زربيان مميزة خالية من الغلوتين.', 4.5, 'assets/images/zurbian.jpg', true, false, false, true, '[{"id":"portion-choice","name":"Protein & Portion (Required)","type":"radio","name_ar":"الخيار والكمية (مطلوب)","options":[{"id":"chk-1","name":"1 Chicken","price":0,"default":true,"name_ar":"دجاجة"},{"id":"chk-2","name":"2 Chickens","price":7,"default":false,"name_ar":"دجاجتين"},{"id":"meat-1kg","name":"1 KG Meat","price":7,"default":false,"name_ar":"1 ك لحم"},{"id":"meat-2kg","name":"2 KG Meat","price":20,"default":false,"name_ar":"2 ك لحم"}],"required":true}]'::jsonb, '[{"id":"extra-daqoos","name":"Extra Daqoos Sauce","type":"add","price":0.5,"name_ar":"دقوس إضافي"},{"id":"extra-almonds","name":"Roasted Almonds & Nuts","type":"add","price":0.5,"name_ar":"لوز ومكسرات محمصة"}]'::jsonb, '[{"id":"rice","desc":"Fragrant basmati rice","icon":"assets/images/ing_bun.png","name":"Basmati Rice","name_ar":"أرز بسمتي","removable":false},{"id":"protein","desc":"Choice of fresh chicken or tender meat","icon":"assets/images/ing_chicken.png","name":"Chicken or Meat Choice","name_ar":"خيار الدجاج أو اللحم","removable":false},{"id":"potato","desc":"Tender spiced potatoes","icon":"assets/images/ing_bun.png","name":"Golden Potatoes","name_ar":"بطاطا","removable":false},{"id":"veggies","desc":"Caramelized onions and tomatoes","icon":"assets/images/ing_tomato.png","name":"Onions & Tomatoes","name_ar":"بصل وطماطم","removable":false},{"id":"spices","desc":"Gluten-free Yemeni spices","icon":"assets/images/ing_sauce.png","name":"Dried Lime & Zurbian Spices","name_ar":"لومي وبهارات مميزة خالية من الغلوتين","removable":false}]'::jsonb, 55),
('kebab-hindi', 'main-dishes', 'Indian Kebab', 'كباب هندي', 'Oven-baked kebab fingers with olive oil served over roasted tomato sauce with toasted nuts, served with basmati rice. Available with fresh chicken or meat.', 'كباب مشوي بالفرن، زيت زيتون، يقدم على أرضية من صوص الطماطم المشوية، مكسرات، يقدم مع الرز البسمتي. متوفر بالدجاج أو اللحم.', 5.5, 'assets/images/tawasi_kebab_hindi.webp', true, false, false, true, '[{"id":"portion-choice","name":"Protein & Portion (Required)","type":"radio","name_ar":"الخيار والكمية (مطلوب)","options":[{"id":"chk-1","name":"1 Chicken","price":0,"default":true,"name_ar":"دجاجة"},{"id":"chk-2","name":"2 Chickens","price":7,"default":false,"name_ar":"دجاجتين"},{"id":"meat-1kg","name":"1 KG Meat","price":7,"default":false,"name_ar":"1 ك لحم"},{"id":"meat-2kg","name":"2 KG Meat","price":20,"default":false,"name_ar":"2 ك لحم"}],"required":true}]'::jsonb, '[{"id":"extra-daqoos","name":"Extra Daqoos Sauce","type":"add","price":0.5,"name_ar":"دقوس إضافي"},{"id":"extra-almonds","name":"Roasted Almonds & Nuts","type":"add","price":0.5,"name_ar":"لوز ومكسرات محمصة"}]'::jsonb, '[{"id":"kebab","desc":"Seasoned spiced kebab fingers","icon":"assets/images/ing_chicken.png","name":"Baked Kebab Fingers","name_ar":"كباب مشوي بالفرن","removable":false},{"id":"sauce","desc":"Charred tomato sauce and olive oil","icon":"assets/images/ing_tomato.png","name":"Roasted Tomato Sauce & Olive Oil","name_ar":"أرضية من صوص الطماطم المشوية وزيت زيتون","removable":false},{"id":"nuts","desc":"Crunchy toasted nuts","icon":"assets/images/ing_bun.png","name":"Toasted Nuts","name_ar":"مكسرات محمصة","removable":false},{"id":"rice","desc":"Gluten-free basmati rice","icon":"assets/images/ing_bun.png","name":"Basmati Rice","name_ar":"أرز بسمتي","removable":false}]'::jsonb, 62),
('chicken-madghout', 'main-dishes', 'Chicken Madghout', 'دجاج مضغوط', 'Basmati rice and meat or chicken pressure-cooked together for concentrated rich flavor, with onions, dried lime, and special spices. Available with fresh chicken or tender meat.', 'قطع الدجاج أو اللحم والأرز البسمتي مطبوخة معاً في قدر الضغط لنكهة مركزة، بصل، لومي، وبهارات خاصة خالية من الغلوتين.', 4.5, 'assets/images/tawasi_madghout.jpg', true, false, false, true, '[{"id":"portion-choice","name":"Protein & Portion (Required)","type":"radio","name_ar":"الخيار والكمية (مطلوب)","options":[{"id":"chk-1","name":"1 Chicken","price":0,"default":true,"name_ar":"دجاجة"},{"id":"chk-2","name":"2 Chickens","price":7,"default":false,"name_ar":"دجاجتين"},{"id":"meat-1kg","name":"1 KG Meat","price":7,"default":false,"name_ar":"1 ك لحم"},{"id":"meat-2kg","name":"2 KG Meat","price":20,"default":false,"name_ar":"2 ك لحم"}],"required":true}]'::jsonb, '[{"id":"extra-daqoos","name":"Extra Daqoos Sauce","type":"add","price":0.5,"name_ar":"دقوس إضافي"},{"id":"extra-almonds","name":"Roasted Almonds & Nuts","type":"add","price":0.5,"name_ar":"لوز ومكسرات محمصة"}]'::jsonb, '[{"id":"rice","desc":"Concentrated savory basmati rice","icon":"assets/images/ing_bun.png","name":"Pressure-Cooked Basmati Rice","name_ar":"أرز بسمتي مطبوخ بقدر الضغط","removable":false},{"id":"protein","desc":"Choice of fresh chicken or tender meat","icon":"assets/images/ing_chicken.png","name":"Chicken or Meat Choice","name_ar":"خيار الدجاج أو اللحم","removable":false},{"id":"aromatics","desc":"Aromatic base","icon":"assets/images/ing_tomato.png","name":"Onions & Dried Lime","name_ar":"بصل ولومي","removable":false},{"id":"spices","desc":"Signature concentrated spices","icon":"assets/images/ing_sauce.png","name":"Special Gluten-Free Spices","name_ar":"بهارات خاصة خالية من الغلوتين","removable":false}]'::jsonb, 57),
('zarb', 'main-dishes', 'Zarb', 'زرب', 'Authentic underground-style smoked basmati rice infused with onions, dried lime, and signature Zarb spices. Available with fresh chicken or tender meat.', 'أرز بسمتي مدخن على الطريقة التراثية مع البصل واللومي وبهارات الزرب الخاصة الخالية من الغلوتين. متوفر بخيار الدجاج أو اللحم.', 4.5, 'assets/images/tawasi_zarb.jpg', true, false, false, true, '[{"id":"portion-choice","name":"Protein & Portion (Required)","type":"radio","name_ar":"الخيار والكمية (مطلوب)","options":[{"id":"chk-1","name":"1 Chicken","price":0,"default":true,"name_ar":"دجاجة"},{"id":"chk-2","name":"2 Chickens","price":7,"default":false,"name_ar":"دجاجتين"},{"id":"meat-1kg","name":"1 KG Meat","price":7,"default":false,"name_ar":"1 ك لحم"},{"id":"meat-2kg","name":"2 KG Meat","price":20,"default":false,"name_ar":"2 ك لحم"}],"required":true}]'::jsonb, '[{"id":"extra-daqoos","name":"Extra Daqoos Sauce","type":"add","price":0.5,"name_ar":"دقوس إضافي"},{"id":"extra-almonds","name":"Roasted Almonds & Nuts","type":"add","price":0.5,"name_ar":"لوز ومكسرات محمصة"}]'::jsonb, '[{"id":"rice","desc":"Slow-smoked basmati rice","icon":"assets/images/ing_bun.png","name":"Smoked Zarb Basmati Rice","name_ar":"أرز بسمتي مدخن","removable":false},{"id":"protein","desc":"Choice of fresh chicken or tender meat","icon":"assets/images/ing_chicken.png","name":"Chicken or Meat Choice","name_ar":"خيار الدجاج أو اللحم","removable":false},{"id":"aromatics","desc":"Aromatic seasoned base","icon":"assets/images/ing_tomato.png","name":"Onions & Dried Lime","name_ar":"بصل ولومي","removable":false},{"id":"spices","desc":"Authentic desert underground spices","icon":"assets/images/ing_sauce.png","name":"Gluten-Free Zarb Spices","name_ar":"بهارات زرب خالية من الغلوتين","removable":false}]'::jsonb, 52),
('mandi', 'main-dishes', 'Mandi', 'مندي', 'Authentic smoked basmati rice cooked to perfection with onions, dried lime, and traditional Mandi spices. Available with fresh chicken or tender meat.', 'أرز بسمتي مدخن بنكهة المندي التراثية مع البصل واللومي وبهارات المندي الخالية من الغلوتين. متوفر بخيار الدجاج أو اللحم.', 4.5, 'assets/images/tawasi_mandi.jpg', true, true, true, true, '[{"id":"portion-choice","name":"Protein & Portion (Required)","type":"radio","name_ar":"الخيار والكمية (مطلوب)","options":[{"id":"chk-1","name":"1 Chicken","price":0,"default":true,"name_ar":"دجاجة"},{"id":"chk-2","name":"2 Chickens","price":7,"default":false,"name_ar":"دجاجتين"},{"id":"meat-1kg","name":"1 KG Meat","price":7,"default":false,"name_ar":"1 ك لحم"},{"id":"meat-2kg","name":"2 KG Meat","price":20,"default":false,"name_ar":"2 ك لحم"}],"required":true}]'::jsonb, '[{"id":"extra-daqoos","name":"Extra Daqoos Sauce","type":"add","price":0.5,"name_ar":"دقوس إضافي"},{"id":"extra-almonds","name":"Roasted Almonds & Nuts","type":"add","price":0.5,"name_ar":"لوز ومكسرات محمصة"}]'::jsonb, '[{"id":"rice","desc":"Slow-smoked Yemeni mandi rice","icon":"assets/images/ing_bun.png","name":"Smoked Basmati Rice","name_ar":"أرز بسمتي مدخن","removable":false},{"id":"protein","desc":"Choice of fresh chicken or tender meat","icon":"assets/images/ing_chicken.png","name":"Chicken or Meat Choice","name_ar":"خيار الدجاج أو اللحم","removable":false},{"id":"aromatics","desc":"Aromatic onions and sun-dried black lime","icon":"assets/images/ing_tomato.png","name":"Onions & Dried Lime","name_ar":"بصل ولومي","removable":false},{"id":"spices","desc":"Handcrafted authentic mandi spice blend","icon":"assets/images/ing_sauce.png","name":"Gluten-Free Mandi Spices","name_ar":"بهارات مندي خالية من الغلوتين","removable":false}]'::jsonb, 53),
('kabsa', 'main-dishes', 'Kabsa', 'كبسة خليجية', 'Fragrant basmati rice infused with onions, tomatoes, tomato paste, dried lime, and authentic Khaleeji Kabsa spices. Available with fresh chicken or tender meat.', 'أرز بسمتي مبهر مع قطع الدجاج أو اللحم، بصل، طماطم، معجون طماطم، لومي، وبهارات كبسة خالية من الغلوتين. متوفر بخيار الدجاج أو اللحم.', 5.5, 'assets/images/tawasi_kabsa.jpg', true, true, true, true, '[{"id":"portion-choice","name":"Protein & Portion (Required)","type":"radio","name_ar":"الخيار والكمية (مطلوب)","options":[{"id":"chk-1","name":"1 Chicken","price":0,"default":true,"name_ar":"دجاجة"},{"id":"chk-2","name":"2 Chickens","price":7,"default":false,"name_ar":"دجاجتين"},{"id":"meat-1kg","name":"1 KG Meat","price":7,"default":false,"name_ar":"1 ك لحم"},{"id":"meat-2kg","name":"2 KG Meat","price":20,"default":false,"name_ar":"2 ك لحم"}],"required":true}]'::jsonb, '[{"id":"extra-daqoos","name":"Extra Daqoos Sauce","type":"add","price":0.5,"name_ar":"دقوس إضافي"},{"id":"extra-almonds","name":"Roasted Almonds & Nuts","type":"add","price":0.5,"name_ar":"لوز ومكسرات محمصة"}]'::jsonb, '[{"id":"rice","desc":"Aromatic basmati rice","icon":"assets/images/ing_bun.png","name":"Basmati Rice","name_ar":"أرز بسمتي","removable":false},{"id":"protein","desc":"Choice of fresh chicken or tender meat","icon":"assets/images/ing_chicken.png","name":"Chicken or Meat Choice","name_ar":"خيار الدجاج أو اللحم","removable":false},{"id":"veggies","desc":"Fresh onions, tomatoes, and rich paste","icon":"assets/images/ing_tomato.png","name":"Onions, Tomatoes & Tomato Paste","name_ar":"بصل وطماطم ومعجون طماطم","removable":false},{"id":"spices","desc":"Signature Gulf kabsa spices and dried lime","icon":"assets/images/ing_sauce.png","name":"Dried Lime & Gluten-Free Kabsa Spices","name_ar":"لومي وبهارات كبسة خالية من الغلوتين","removable":false}]'::jsonb, 50),
('dawood-basha', 'main-dishes', 'Dawood Basha', 'داوود باشا', 'Handcrafted meatballs with special seasoning, aromatic herbs, and extra virgin olive oil simmered in black pepper tomato sauce, served with rice. Available with fresh chicken or meat.', 'كرات اللحم بالتتبيلة الخاصة، أعشاب عطرية، زيت زيتون، وصلصة الطماطم الخاصة بالفلفل الأسود، يقدم مع الأرز. متوفر بالدجاج أو اللحم.', 5, 'assets/images/tawasi_dawood_basha.webp', true, false, false, true, '[{"id":"portion-choice","name":"Protein & Portion (Required)","type":"radio","name_ar":"الخيار والكمية (مطلوب)","options":[{"id":"chk-1","name":"1 Chicken","price":0,"default":true,"name_ar":"دجاجة"},{"id":"chk-2","name":"2 Chickens","price":7,"default":false,"name_ar":"دجاجتين"},{"id":"meat-1kg","name":"1 KG Meat","price":7,"default":false,"name_ar":"1 ك لحم"},{"id":"meat-2kg","name":"2 KG Meat","price":20,"default":false,"name_ar":"2 ك لحم"}],"required":true}]'::jsonb, '[{"id":"extra-daqoos","name":"Extra Daqoos Sauce","type":"add","price":0.5,"name_ar":"دقوس إضافي"},{"id":"extra-almonds","name":"Roasted Almonds & Nuts","type":"add","price":0.5,"name_ar":"لوز ومكسرات محمصة"}]'::jsonb, '[{"id":"meatballs","desc":"Handcrafted seasoned kofta meatballs","icon":"assets/images/ing_chicken.png","name":"Special Seasoned Meatballs","name_ar":"كرات اللحم بالتتبيلة الخاصة","removable":false},{"id":"herbs-oil","desc":"Fresh fragrant herbs and extra virgin olive oil","icon":"assets/images/ing_lettuce.png","name":"Aromatic Herbs & Olive Oil","name_ar":"أعشاب عطرية وزيت زيتون","removable":false},{"id":"sauce","desc":"Rich seasoned tomato sauce","icon":"assets/images/ing_sauce.png","name":"Black Pepper Tomato Sauce","name_ar":"صلصة الطماطم الخاصة بالفلفل الأسود","removable":false},{"id":"rice","desc":"Gluten-free steamed rice","icon":"assets/images/ing_bun.png","name":"Steamed Rice","name_ar":"أرز فاخر","removable":false}]'::jsonb, 59),
('ouzi', 'main-dishes', 'Ouzi', 'أوزي', 'Fragrant oriental spiced basmati rice with sweet green peas, carrots, toasted nuts, and warming spices. Available with fresh chicken or tender meat.', 'أرز شرقي فاخر مطبوخ مع البازيلاء والجزر والمكسرات المحمصة والتوابل الدافئة. متوفر بخيار الدجاج أو اللحم.', 4.75, 'assets/images/tawasi_ouzi.jpg', true, false, false, true, '[{"id":"portion-choice","name":"Protein & Portion (Required)","type":"radio","name_ar":"الخيار والكمية (مطلوب)","options":[{"id":"chk-1","name":"1 Chicken","price":0,"default":true,"name_ar":"دجاجة"},{"id":"chk-2","name":"2 Chickens","price":7,"default":false,"name_ar":"دجاجتين"},{"id":"meat-1kg","name":"1 KG Meat","price":7,"default":false,"name_ar":"1 ك لحم"},{"id":"meat-2kg","name":"2 KG Meat","price":20,"default":false,"name_ar":"2 ك لحم"}],"required":true}]'::jsonb, '[{"id":"extra-daqoos","name":"Extra Daqoos Sauce","type":"add","price":0.5,"name_ar":"دقوس إضافي"},{"id":"extra-almonds","name":"Roasted Almonds & Nuts","type":"add","price":0.5,"name_ar":"لوز ومكسرات محمصة"}]'::jsonb, '[{"id":"rice","desc":"Seasoned oriental spiced rice","icon":"assets/images/ing_bun.png","name":"Oriental Basmati Rice","name_ar":"أرز شرقي فاخر","removable":false},{"id":"protein","desc":"Choice of fresh chicken or tender meat","icon":"assets/images/ing_chicken.png","name":"Chicken or Meat Choice","name_ar":"خيار الدجاج أو اللحم","removable":false},{"id":"veggies","desc":"Tender sweet vegetables","icon":"assets/images/ing_lettuce.png","name":"Green Peas & Carrots","name_ar":"بازيلاء وجزر","removable":false},{"id":"nuts","desc":"Golden almonds and aromatics","icon":"assets/images/ing_bun.png","name":"Toasted Nuts & Special Spices","name_ar":"مكسرات محمصة وتوابل دافئة","removable":false}]'::jsonb, 54),
('tahini-kofta', 'main-dishes', 'Tahini Kofta', 'كفتة بالطحينية', 'Oven-baked kofta fingers with potato and onion slices in creamy lemon tahini sauce with garlic and pepper, served with basmati rice. Available with fresh chicken or meat.', 'أصابع الكفتة مشوية بالفرن مع شرحات البطاطا والبصل بصوص الطحينية والليمون، ثوم، فلفل، يقدم مع رز بسمتي. متوفرة بالدجاج أو اللحم.', 5.75, 'assets/images/tawasi_tahini_kofta.webp', true, false, false, true, '[{"id":"portion-choice","name":"Protein & Portion (Required)","type":"radio","name_ar":"الخيار والكمية (مطلوب)","options":[{"id":"chk-1","name":"1 Chicken","price":0,"default":true,"name_ar":"دجاجة"},{"id":"chk-2","name":"2 Chickens","price":7,"default":false,"name_ar":"دجاجتين"},{"id":"meat-1kg","name":"1 KG Meat","price":7,"default":false,"name_ar":"1 ك لحم"},{"id":"meat-2kg","name":"2 KG Meat","price":20,"default":false,"name_ar":"2 ك لحم"}],"required":true}]'::jsonb, '[{"id":"extra-daqoos","name":"Extra Daqoos Sauce","type":"add","price":0.5,"name_ar":"دقوس إضافي"},{"id":"extra-almonds","name":"Roasted Almonds & Nuts","type":"add","price":0.5,"name_ar":"لوز ومكسرات محمصة"}]'::jsonb, '[{"id":"kofta","desc":"Seasoned baked kofta","icon":"assets/images/ing_chicken.png","name":"Baked Kofta Fingers","name_ar":"أصابع الكفتة مشوية بالفرن","removable":false},{"id":"potato-onion","desc":"Oven-baked potato and onion slices","icon":"assets/images/ing_bun.png","name":"Potatoes & Sliced Onions","name_ar":"شرحات البطاطا والبصل","removable":false},{"id":"tahini","desc":"Creamy lemon tahini sauce with garlic and pepper","icon":"assets/images/ing_sauce.png","name":"Lemon Tahini Sauce, Garlic & Pepper","name_ar":"صوص الطحينية والليمون وثوم وفلفل","removable":false},{"id":"rice","desc":"Gluten-free basmati rice","icon":"assets/images/ing_bun.png","name":"Basmati Rice","name_ar":"أرز بسمتي","removable":false}]'::jsonb, 61)
